namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = "";
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Explore abstract structures, quantities, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and critical analysis of texts." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Understanding the fundamental laws of nature and the universe." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Examination of past events, cultures, and civilizations." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to the field of computer science covering computational thinking, basic programming in Python, data representation, and an overview of how computers work. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has over 15 years of experience teaching introductory courses. Her research focuses on CS education and making computing accessible to all students.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures including arrays, linked lists, trees, hash tables, and graphs. Analysis of algorithm efficiency using Big-O notation. Prerequisite: CS 101.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park received his Ph.D. from Stanford University and specializes in algorithm design and competitive programming. He has published over 40 papers in top-tier conferences.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
            new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Design and implementation of relational databases, SQL, normalization, transaction processing, and an introduction to NoSQL systems. Includes a semester-long project building a real-world database application.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez is a former database architect at Oracle with a Ph.D. from UC Berkeley. She brings extensive industry experience to the classroom and mentors students on applied database projects.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
            new() { Id = 4, Code = "CS 450", Title = "Artificial Intelligence", Description = "Foundations of AI including search algorithms, knowledge representation, machine learning basics, neural networks, and natural language processing. Students complete hands-on projects using modern AI frameworks.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has over 15 years of experience teaching introductory courses. Her research focuses on CS education and making computing accessible to all students.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },

            // Mathematics
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to rates of change, optimization, and area. Suitable for students in science, engineering, and mathematics.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim earned his Ph.D. from Princeton University and is a recipient of the university's Distinguished Teaching Award. He is known for making calculus intuitive and engaging.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations. Essential for students pursuing advanced work in mathematics, physics, computer science, or engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Elena Petrov", InstructorBio = "Dr. Petrov completed her doctorate at the University of Cambridge and specializes in abstract algebra. She has authored two widely used textbooks on linear algebra.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 7, Code = "MATH 310", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis. Applications drawn from biology, economics, and social sciences.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim earned his Ph.D. from Princeton University and is a recipient of the university's Distinguished Teaching Award. He is known for making calculus intuitive and engaging.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 8, Code = "MATH 420", Title = "Real Analysis", Description = "Rigorous treatment of limits, continuity, differentiation, and integration on the real line. Emphasis on proofs and mathematical reasoning. Prerequisite: Calculus II.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", InstructorName = "Dr. Elena Petrov", InstructorBio = "Dr. Petrov completed her doctorate at the University of Cambridge and specializes in abstract algebra. She has authored two widely used textbooks on linear algebra.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },

            // English
            new() { Id = 9, Code = "ENG 101", Title = "Expository Writing", Description = "Develop skills in academic writing through essay composition, argumentation, source analysis, and revision. Students produce a portfolio of polished essays by the end of the semester.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. Angela Morrison", InstructorBio = "Prof. Morrison is an award-winning author and writing instructor who has taught composition for over 20 years. Her essays have appeared in The New Yorker, The Atlantic, and Harper's.", DepartmentId = 3, DepartmentName = "English", IsFeatured = false },
            new() { Id = 10, Code = "ENG 215", Title = "American Literature", Description = "Survey of American literary traditions from the colonial period to the present, including works by Hawthorne, Whitman, Dickinson, Fitzgerald, Morrison, and contemporary voices.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Thomas Reed", InstructorBio = "Dr. Reed specializes in 20th-century American fiction and holds a Ph.D. from Yale University. He has published extensively on the works of Toni Morrison and James Baldwin.", DepartmentId = 3, DepartmentName = "English", IsFeatured = true },
            new() { Id = 11, Code = "ENG 330", Title = "Shakespeare", Description = "Close reading of Shakespeare's major plays—comedies, tragedies, and histories—with attention to language, performance, and cultural context. Includes attendance at a live performance.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", InstructorName = "Dr. Thomas Reed", InstructorBio = "Dr. Reed specializes in 20th-century American fiction and holds a Ph.D. from Yale University. He has published extensively on the works of Toni Morrison and James Baldwin.", DepartmentId = 3, DepartmentName = "English", IsFeatured = false },

            // Physics
            new() { Id = 12, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, heat, and waves. Covers Newton's laws, energy, momentum, rotational dynamics, oscillations, and thermodynamics. Includes a weekly laboratory component.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM, Lab: Thu 2:00–4:00 PM", InstructorName = "Dr. Alan Yoshida", InstructorBio = "Dr. Yoshida is an experimental physicist with a Ph.D. from Caltech. His research in condensed matter physics has been published in Physical Review Letters and Nature Physics.", DepartmentId = 4, DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 13, Code = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Builds on General Physics I to explore electromagnetic theory, wave optics, and introductory quantum phenomena.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM, Lab: Fri 1:00–3:00 PM", InstructorName = "Dr. Alan Yoshida", InstructorBio = "Dr. Yoshida is an experimental physicist with a Ph.D. from Caltech. His research in condensed matter physics has been published in Physical Review Letters and Nature Physics.", DepartmentId = 4, DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 14, Code = "PHYS 350", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, the Schrödinger equation, operators, angular momentum, spin, and the hydrogen atom. Prerequisite: General Physics II and Linear Algebra.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", InstructorName = "Dr. Priya Nair", InstructorBio = "Dr. Nair earned her Ph.D. from the University of Oxford and is a theoretical physicist whose research explores quantum information and entanglement.", DepartmentId = 4, DepartmentName = "Physics", IsFeatured = true },

            // History
            new() { Id = 15, Code = "HIST 101", Title = "World Civilizations I", Description = "Survey of major world civilizations from prehistory through the early modern period, covering Mesopotamia, Egypt, Greece, Rome, China, the Islamic world, and medieval Europe.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Catherine Okafor", InstructorBio = "Dr. Okafor holds a Ph.D. from Columbia University and specializes in ancient and medieval world history. She has led archaeological fieldwork in West Africa and the Mediterranean.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
            new() { Id = 16, Code = "HIST 205", Title = "The American Civil War", Description = "In-depth examination of the causes, course, and consequences of the American Civil War, including slavery, secession, military campaigns, emancipation, and Reconstruction.", Credits = 3, Schedule = "Mon/Wed 1:00–2:20 PM", InstructorName = "Dr. William Grant", InstructorBio = "Dr. Grant is a Civil War historian with a Ph.D. from the University of Virginia. He has authored three books and is a frequent consultant for historical documentaries.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
            new() { Id = 17, Code = "HIST 340", Title = "Modern East Asia", Description = "Political, economic, and cultural history of China, Japan, and Korea from the 19th century to the present. Topics include imperialism, revolution, economic development, and globalization.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", InstructorName = "Dr. Catherine Okafor", InstructorBio = "Dr. Okafor holds a Ph.D. from Columbia University and specializes in ancient and medieval world history. She has led archaeological fieldwork in West Africa and the Mediterranean.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public List<Course> GetCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request) => true;
}

