<PageTitle>University Course Catalog</PageTitle>

<div class="hero-section text-center mb-5">
    <h1 class="display-4 fw-bold">Welcome to the University Course Catalog</h1>
    <p class="lead text-muted">Explore our diverse range of courses across five departments. Find the right courses for your academic journey and enroll today.</p>
    <a href="/courses" class="btn btn-primary btn-lg mt-2">Browse All Courses</a>
</div>

<h2 class="mb-3">Featured Courses</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4 mb-5">
    @foreach (var course in CatalogService.GetFeaturedCourses())
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">@course.Title</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@course.Code &middot; @course.Credits Credits</h6>
                    <p class="card-text text-muted small">@course.DepartmentName</p>
                    <p class="card-text">@Truncate(course.Description, 120)</p>
                </div>
                <div class="card-footer bg-transparent border-top-0">
                    <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                </div>
            </div>
        </div>
    }
</div>

<h2 class="mb-3">Departments</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4 mb-4">
    @foreach (var dept in CatalogService.GetDepartments())
    {
        <div class="col">
            <div class="card h-100 border-primary">
                <div class="card-body">
                    <h5 class="card-title">@dept.Name</h5>
                    <p class="card-text text-muted">@dept.Description</p>
                </div>
                <div class="card-footer bg-transparent border-top-0">
                    <a href="/courses?DepartmentId=@dept.Id" class="btn btn-outline-primary btn-sm">View Courses</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string Truncate(string text, int maxLength)
    {
        if (string.IsNullOrEmpty(text) || text.Length <= maxLength) return text;
        return text[..maxLength] + "…";
    }
}

